INSERT INTO recipes (id, name, description) VALUES ('d00244f1-6096-4115-830d-5613e8be412c', 'Owsianka z jabłkiem i cynamonem', 'Ciepła owsianka na rozgrzanie – idealna na zimowe śniadanie.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('d00244f1-6096-4115-830d-5613e8be412c', 'Płatki owsiane', 50, 'g', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('d00244f1-6096-4115-830d-5613e8be412c', 'Mleko', 200, 'ml', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('d00244f1-6096-4115-830d-5613e8be412c', 'Jabłka', 1, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('d00244f1-6096-4115-830d-5613e8be412c', 'Masło', 1, 'szt', 4);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('d00244f1-6096-4115-830d-5613e8be412c', 1, 'Płatki zalać mlekiem, gotować na wolnym ogniu 5–7 minut, często mieszając.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('d00244f1-6096-4115-830d-5613e8be412c', 2, 'Jabłko obrać, zetrzeć na tarce. Dodać do owsianki na 2 min przed końcem.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('d00244f1-6096-4115-830d-5613e8be412c', 3, 'Przed podaniem dodać odrobinę masła. Posypać cynamonem.');
INSERT INTO recipes (id, name, description) VALUES ('dc5bc776-901b-42e4-a7b1-b492dbd105ef', 'Jajecznica z pomidorami', 'Klasyczna jajecznica z dodatkiem świeżych pomidorów.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('dc5bc776-901b-42e4-a7b1-b492dbd105ef', 'Jajka', 3, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('dc5bc776-901b-42e4-a7b1-b492dbd105ef', 'Pomidory', 1, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('dc5bc776-901b-42e4-a7b1-b492dbd105ef', 'Masło', 1, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('dc5bc776-901b-42e4-a7b1-b492dbd105ef', 'Chleb', 2, 'szt', 4);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('dc5bc776-901b-42e4-a7b1-b492dbd105ef', 1, 'Jajka roztrzepać w miseczce. Pomidor pokroić w kostkę.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('dc5bc776-901b-42e4-a7b1-b492dbd105ef', 2, 'Na patelni rozpuścić masło, wlać jajka, mieszać. Gdy się zetną, dodać pomidory.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('dc5bc776-901b-42e4-a7b1-b492dbd105ef', 3, 'Doprawić solą i pieprzem. Podawać z pieczywem.');
INSERT INTO recipes (id, name, description) VALUES ('a0685c9a-765c-4c9f-989e-a877601928c9', 'Kanapki z twarogiem i rzodkiewką', 'Lekkie śniadanie – twaróg z rzodkiewką na chrupiącym chlebie.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a0685c9a-765c-4c9f-989e-a877601928c9', 'Chleb', 1, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a0685c9a-765c-4c9f-989e-a877601928c9', 'Twaróg', 150, 'g', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a0685c9a-765c-4c9f-989e-a877601928c9', 'Ogórki', 0.5, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a0685c9a-765c-4c9f-989e-a877601928c9', 'Rzodkiewka', 4, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a0685c9a-765c-4c9f-989e-a877601928c9', 'Masło', 1, 'szt', 5);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('a0685c9a-765c-4c9f-989e-a877601928c9', 1, 'Chleb pokroić w kromki, posmarować masłem.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('a0685c9a-765c-4c9f-989e-a877601928c9', 2, 'Twaróg rozgnieść widelcem, doprawić solą. Ogórek i rzodkiewkę pokroić w plasterki.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('a0685c9a-765c-4c9f-989e-a877601928c9', 3, 'Na chleb nałożyć twaróg, ułożyć warzywa. Podawać od razu.');
INSERT INTO recipes (id, name, description) VALUES ('eb8b7bbd-e8c4-460b-a3ef-6bdd9d37803c', 'Smoothie bananowo-jogurtowe', 'Szybki koktajl na śniadanie lub drugie śniadanie.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('eb8b7bbd-e8c4-460b-a3ef-6bdd9d37803c', 'Banany', 1, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('eb8b7bbd-e8c4-460b-a3ef-6bdd9d37803c', 'Jogurt naturalny', 1, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('eb8b7bbd-e8c4-460b-a3ef-6bdd9d37803c', 'Mleko', 100, 'ml', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('eb8b7bbd-e8c4-460b-a3ef-6bdd9d37803c', 'Płatki owsiane', 1, 'szt', 4);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('eb8b7bbd-e8c4-460b-a3ef-6bdd9d37803c', 1, 'Banana obrać, pokroić. Wrzucić do blendera z jogurtem i mlekiem.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('eb8b7bbd-e8c4-460b-a3ef-6bdd9d37803c', 2, 'Zmiksować na gładki koktajl. Opcjonalnie dodać łyżkę płatków owsianych.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('eb8b7bbd-e8c4-460b-a3ef-6bdd9d37803c', 3, 'Przelać do szklanki, podawać od razu.');
INSERT INTO recipes (id, name, description) VALUES ('faec0a09-1627-47af-9554-d0004980a917', 'Tosty z serem i szynką', 'Chrupiące tosty z roztopionym serem – dzieci je uwielbiają.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('faec0a09-1627-47af-9554-d0004980a917', 'Pieczywo tostowe', 4, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('faec0a09-1627-47af-9554-d0004980a917', 'Ser żółty', 2, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('faec0a09-1627-47af-9554-d0004980a917', 'Szynka', 2, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('faec0a09-1627-47af-9554-d0004980a917', 'Masło', 1, 'szt', 4);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('faec0a09-1627-47af-9554-d0004980a917', 1, 'Kromki tostowe posmarować masłem z jednej strony.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('faec0a09-1627-47af-9554-d0004980a917', 2, 'Na dwóch kromkach (nieposmarowaną stroną do góry) ułożyć szynkę i ser, przykryć drugimi kromkami (masłem na zewnątrz).');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('faec0a09-1627-47af-9554-d0004980a917', 3, 'Smażyć na patelni lub w opiekaczu do zrumienienia z obu stron.');
INSERT INTO recipes (id, name, description) VALUES ('f05bf1c4-6ab9-4b13-9480-c4e8dee5e523', 'Omlet z warzywami', 'Puszysty omlet z pomidorem i serem.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('f05bf1c4-6ab9-4b13-9480-c4e8dee5e523', 'Jajka', 3, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('f05bf1c4-6ab9-4b13-9480-c4e8dee5e523', 'Pomidory', 1, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('f05bf1c4-6ab9-4b13-9480-c4e8dee5e523', 'Ser żółty', 50, 'g', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('f05bf1c4-6ab9-4b13-9480-c4e8dee5e523', 'Olej', 1, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('f05bf1c4-6ab9-4b13-9480-c4e8dee5e523', 'Chleb', 1, 'szt', 5);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('f05bf1c4-6ab9-4b13-9480-c4e8dee5e523', 1, 'Jajka roztrzepać, doprawić solą. Warzywa pokroić w drobną kostkę, ser zetrzeć.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('f05bf1c4-6ab9-4b13-9480-c4e8dee5e523', 2, 'Na patelni rozgrzać olej, wlać jajka. Gdy dół się zetnie, posypać warzywami i serem.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('f05bf1c4-6ab9-4b13-9480-c4e8dee5e523', 3, 'Złożyć omlet na pół lub przewrócić. Podawać z pieczywem.');
INSERT INTO recipes (id, name, description) VALUES ('9cccfe31-2b92-43d2-9623-c25c42fe5f0c', 'Jogurt z owocami i musli', 'Śniadanie bez gotowania – jogurt, owoce i płatki.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('9cccfe31-2b92-43d2-9623-c25c42fe5f0c', 'Jogurt naturalny', 1, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('9cccfe31-2b92-43d2-9623-c25c42fe5f0c', 'Banany', 0.5, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('9cccfe31-2b92-43d2-9623-c25c42fe5f0c', 'Jabłka', 0.5, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('9cccfe31-2b92-43d2-9623-c25c42fe5f0c', 'Płatki owsiane', 2, 'szt', 4);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('9cccfe31-2b92-43d2-9623-c25c42fe5f0c', 1, 'Jogurt przełożyć do miseczki. Banana i jabłko pokroić w plasterki.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('9cccfe31-2b92-43d2-9623-c25c42fe5f0c', 2, 'Na jogurt położyć owoce, posypać płatkami owsianymi (lub gotowym musli).');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('9cccfe31-2b92-43d2-9623-c25c42fe5f0c', 3, 'Opcjonalnie skropić miodem. Podawać od razu.');
INSERT INTO recipes (id, name, description) VALUES ('fed71d75-4e00-4400-9d3c-17c652c18066', 'Zupa pomidorowa z makaronem', 'Prosta zupa pomidorowa – klasyka obiadowa.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('fed71d75-4e00-4400-9d3c-17c652c18066', 'Pomidory', 4, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('fed71d75-4e00-4400-9d3c-17c652c18066', 'Makaron', 200, 'g', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('fed71d75-4e00-4400-9d3c-17c652c18066', 'Sól', 1, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('fed71d75-4e00-4400-9d3c-17c652c18066', 'Olej', 2, 'szt', 4);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('fed71d75-4e00-4400-9d3c-17c652c18066', 1, 'Pomidory sparzyć, obrać ze skórki i pokroić w kostkę.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('fed71d75-4e00-4400-9d3c-17c652c18066', 2, 'W garnku rozgrzać olej, wrzucić pomidory i dusić kilka minut. Dolać ok. 1 l wody, doprawić solą, gotować 15 min.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('fed71d75-4e00-4400-9d3c-17c652c18066', 3, 'Dodać makaron, gotować do miękkości według opisu na opakowaniu. Podawać z bazylią.');
INSERT INTO recipes (id, name, description) VALUES ('02e59416-47a0-4ecd-82c7-26ae1b8d00f0', 'Kurczak z ryżem i warzywami', 'Danie jednogarnkowe – kurczak, ryż i marchewka.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('02e59416-47a0-4ecd-82c7-26ae1b8d00f0', 'Kurczak', 300, 'g', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('02e59416-47a0-4ecd-82c7-26ae1b8d00f0', 'Ryż', 150, 'g', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('02e59416-47a0-4ecd-82c7-26ae1b8d00f0', 'Marchew', 2, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('02e59416-47a0-4ecd-82c7-26ae1b8d00f0', 'Olej', 1, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('02e59416-47a0-4ecd-82c7-26ae1b8d00f0', 'Sól', 1, 'szt', 5);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('02e59416-47a0-4ecd-82c7-26ae1b8d00f0', 1, 'Kurczaka pokroić w kostkę, marchew w plasterki. Ryż opłukać.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('02e59416-47a0-4ecd-82c7-26ae1b8d00f0', 2, 'Na oleju zeszklić kurczaka, dodać marchew, chwilę dusić. Dolać 400 ml wody, wsypać ryż, doprawić solą.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('02e59416-47a0-4ecd-82c7-26ae1b8d00f0', 3, 'Gotować pod przykryciem ok. 20 min, aż ryż wchłonie płyn. Podawać na ciepło.');
INSERT INTO recipes (id, name, description) VALUES ('4235f476-7c09-4c67-9b5a-0f9a19836c90', 'Spaghetti bolognese', 'Makaron z sosem mięsnym – obiad dla całej rodziny.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('4235f476-7c09-4c67-9b5a-0f9a19836c90', 'Makaron', 300, 'g', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('4235f476-7c09-4c67-9b5a-0f9a19836c90', 'Wołowina', 300, 'g', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('4235f476-7c09-4c67-9b5a-0f9a19836c90', 'Pomidory', 3, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('4235f476-7c09-4c67-9b5a-0f9a19836c90', 'Marchew', 1, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('4235f476-7c09-4c67-9b5a-0f9a19836c90', 'Olej', 2, 'szt', 5);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('4235f476-7c09-4c67-9b5a-0f9a19836c90', 'Sól', 1, 'szt', 6);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('4235f476-7c09-4c67-9b5a-0f9a19836c90', 1, 'Makaron ugotować al dente według opisu na opakowaniu. Odcedzić.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('4235f476-7c09-4c67-9b5a-0f9a19836c90', 2, 'Mięso pokroić i podsmażyć na oleju. Dodać drobno pokrojoną marchew i pomidory (lub passatę), dusić 20 min. Doprawić solą i pieprzem.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('4235f476-7c09-4c67-9b5a-0f9a19836c90', 3, 'Podawać makaron z sosem, posypać parmezanem lub bazylią.');
INSERT INTO recipes (id, name, description) VALUES ('a7fbb639-07d9-4ae2-a6d9-eadc9cb01d06', 'Zupa jarzynowa', 'Lekka zupa na wywarze warzywnym z makaronem.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a7fbb639-07d9-4ae2-a6d9-eadc9cb01d06', 'Marchew', 2, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a7fbb639-07d9-4ae2-a6d9-eadc9cb01d06', 'Pietruszka', 1, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a7fbb639-07d9-4ae2-a6d9-eadc9cb01d06', 'Makaron', 100, 'g', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a7fbb639-07d9-4ae2-a6d9-eadc9cb01d06', 'Olej', 1, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a7fbb639-07d9-4ae2-a6d9-eadc9cb01d06', 'Sól', 1, 'szt', 5);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('a7fbb639-07d9-4ae2-a6d9-eadc9cb01d06', 1, 'Warzywa obrać, pokroić w kostkę. W garnku rozgrzać olej, zrumienić warzywa.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('a7fbb639-07d9-4ae2-a6d9-eadc9cb01d06', 2, 'Zalać 1,5 l wody, doprawić solą, gotować 25 min.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('a7fbb639-07d9-4ae2-a6d9-eadc9cb01d06', 3, 'Dodać makaron, gotować do miękkości. Podawać z natką pietruszki.');
INSERT INTO recipes (id, name, description) VALUES ('234f49dc-d9af-49e4-951a-02e2e248b3d0', 'Kotlet schabowy z ziemniakami', 'Tradycyjny kotlet panierowany z ziemniakami i surówką.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('234f49dc-d9af-49e4-951a-02e2e248b3d0', 'Schab wieprzowy', 400, 'g', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('234f49dc-d9af-49e4-951a-02e2e248b3d0', 'Jajka', 1, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('234f49dc-d9af-49e4-951a-02e2e248b3d0', 'Mąka', 3, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('234f49dc-d9af-49e4-951a-02e2e248b3d0', 'Olej', 3, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('234f49dc-d9af-49e4-951a-02e2e248b3d0', 'Marchew', 1, 'szt', 5);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('234f49dc-d9af-49e4-951a-02e2e248b3d0', 'Ogórki', 1, 'szt', 6);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('234f49dc-d9af-49e4-951a-02e2e248b3d0', 1, 'Mięso rozbić tłuczkiem, doprawić solą i pieprzem. Obtoczyć w mące, jajku i bułce tartej.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('234f49dc-d9af-49e4-951a-02e2e248b3d0', 2, 'Smażyć na rozgrzanym oleju z obu stron do zrumienienia. Odłożyć na ręcznik papierowy.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('234f49dc-d9af-49e4-951a-02e2e248b3d0', 3, 'Ziemniaki ugotować. Surówkę zetrzeć z marchewki i ogórka, doprawić. Podawać kotlet z ziemniakami i surówką.');
INSERT INTO recipes (id, name, description) VALUES ('6a424d7c-d526-4497-b804-17f1254641d3', 'Sałatka z kurczakiem i warzywami', 'Lekki obiad – sałatka z grillowanym kurczakiem.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('6a424d7c-d526-4497-b804-17f1254641d3', 'Kurczak', 200, 'g', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('6a424d7c-d526-4497-b804-17f1254641d3', 'Pomidory', 2, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('6a424d7c-d526-4497-b804-17f1254641d3', 'Ogórki', 1, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('6a424d7c-d526-4497-b804-17f1254641d3', 'Olej', 2, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('6a424d7c-d526-4497-b804-17f1254641d3', 'Sól', 1, 'szt', 5);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('6a424d7c-d526-4497-b804-17f1254641d3', 1, 'Kurczaka pokroić w paski, doprawić, usmażyć na oleju do zrumienienia.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('6a424d7c-d526-4497-b804-17f1254641d3', 2, 'Pomidory i ogórek pokroić w kostkę. Wymieszać z kurczakiem w misce.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('6a424d7c-d526-4497-b804-17f1254641d3', 3, 'Skropić olejem, doprawić solą i pieprzem. Można dodać jogurt naturalny zamiast oleju.');
INSERT INTO recipes (id, name, description) VALUES ('2d9eb6ae-e5d7-46cc-a140-a2e8311faaa5', 'Makaron z serem i mlekiem', 'Szybki obiad – makaron zapiekany z serem.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('2d9eb6ae-e5d7-46cc-a140-a2e8311faaa5', 'Makaron', 250, 'g', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('2d9eb6ae-e5d7-46cc-a140-a2e8311faaa5', 'Ser żółty', 100, 'g', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('2d9eb6ae-e5d7-46cc-a140-a2e8311faaa5', 'Mleko', 100, 'ml', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('2d9eb6ae-e5d7-46cc-a140-a2e8311faaa5', 'Masło', 1, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('2d9eb6ae-e5d7-46cc-a140-a2e8311faaa5', 'Sól', 1, 'szt', 5);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('2d9eb6ae-e5d7-46cc-a140-a2e8311faaa5', 1, 'Makaron ugotować al dente, odcedzić. Ser zetrzeć.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('2d9eb6ae-e5d7-46cc-a140-a2e8311faaa5', 2, 'W naczyniu żaroodpornym wymieszać makaron z masłem, mlekiem i większością sera. Doprawić solą.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('2d9eb6ae-e5d7-46cc-a140-a2e8311faaa5', 3, 'Posypać resztą sera, zapiec w piekarniku (180°C) ok. 15 min do zrumienienia.');
INSERT INTO recipes (id, name, description) VALUES ('6236b2e2-79b5-4ad8-9956-20d8dbaca556', 'Kasza gryczana z gulaszem', 'Sycący obiad – kasza z mięsnym gulaszem.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('6236b2e2-79b5-4ad8-9956-20d8dbaca556', 'Kasza gryczana', 200, 'g', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('6236b2e2-79b5-4ad8-9956-20d8dbaca556', 'Wołowina', 350, 'g', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('6236b2e2-79b5-4ad8-9956-20d8dbaca556', 'Marchew', 2, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('6236b2e2-79b5-4ad8-9956-20d8dbaca556', 'Pomidory', 2, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('6236b2e2-79b5-4ad8-9956-20d8dbaca556', 'Olej', 2, 'szt', 5);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('6236b2e2-79b5-4ad8-9956-20d8dbaca556', 'Sól', 1, 'szt', 6);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('6236b2e2-79b5-4ad8-9956-20d8dbaca556', 1, 'Kaszę ugotować według opisu na opakowaniu (zwykle 2 szklanki wody na szklankę kaszy).');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('6236b2e2-79b5-4ad8-9956-20d8dbaca556', 2, 'Mięso pokroić w kostkę, podsmażyć na oleju. Dodać pokrojoną marchew i pomidory, dusić 30 min pod przykryciem. Doprawić.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('6236b2e2-79b5-4ad8-9956-20d8dbaca556', 3, 'Podawać kaszę z gulaszem.');
INSERT INTO recipes (id, name, description) VALUES ('bc213803-b783-4c6d-af23-720c5609ecdb', 'Sałatka warzywna z olejem', 'Prosta sałatka – idealna na lekki obiad lub kolację.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('bc213803-b783-4c6d-af23-720c5609ecdb', 'Pomidory', 2, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('bc213803-b783-4c6d-af23-720c5609ecdb', 'Ogórki', 2, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('bc213803-b783-4c6d-af23-720c5609ecdb', 'Marchew', 1, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('bc213803-b783-4c6d-af23-720c5609ecdb', 'Olej', 1, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('bc213803-b783-4c6d-af23-720c5609ecdb', 'Sól', 1, 'szt', 5);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('bc213803-b783-4c6d-af23-720c5609ecdb', 1, 'Warzywa umyć. Pomidory i ogórki pokroić w kostkę, marchew zetrzeć na tarce.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('bc213803-b783-4c6d-af23-720c5609ecdb', 2, 'Wymieszać w misce, skropić olejem, doprawić solą i pieprzem.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('bc213803-b783-4c6d-af23-720c5609ecdb', 3, 'Opcjonalnie dodać cebulę lub natkę pietruszki. Podawać z pieczywem.');
INSERT INTO recipes (id, name, description) VALUES ('7797cfcd-d034-4e48-b99a-844c971ec08e', 'Kanapki z pastą jajeczną', 'Kolacja w 10 minut – kanapki z jajkiem i ogórkiem.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('7797cfcd-d034-4e48-b99a-844c971ec08e', 'Chleb', 1, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('7797cfcd-d034-4e48-b99a-844c971ec08e', 'Jajka', 2, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('7797cfcd-d034-4e48-b99a-844c971ec08e', 'Ogórki', 0.5, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('7797cfcd-d034-4e48-b99a-844c971ec08e', 'Jogurt naturalny', 1, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('7797cfcd-d034-4e48-b99a-844c971ec08e', 'Masło', 1, 'szt', 5);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('7797cfcd-d034-4e48-b99a-844c971ec08e', 1, 'Jajka ugotować na twardo (ok. 8 min), ostudzić, obrać. Rozgnieść widelcem.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('7797cfcd-d034-4e48-b99a-844c971ec08e', 2, 'Dodać drobno pokrojony ogórek i łyżkę jogurtu, doprawić solą. Wymieszać.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('7797cfcd-d034-4e48-b99a-844c971ec08e', 3, 'Chleb posmarować masłem, nałożyć pastę. Podawać z warzywami.');
INSERT INTO recipes (id, name, description) VALUES ('7bad03a3-086c-4edf-b85f-a6e151abe305', 'Omlet na kolację', 'Szybki omlet z szynką i serem – sycąca kolacja.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('7bad03a3-086c-4edf-b85f-a6e151abe305', 'Jajka', 3, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('7bad03a3-086c-4edf-b85f-a6e151abe305', 'Szynka', 2, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('7bad03a3-086c-4edf-b85f-a6e151abe305', 'Ser żółty', 50, 'g', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('7bad03a3-086c-4edf-b85f-a6e151abe305', 'Olej', 1, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('7bad03a3-086c-4edf-b85f-a6e151abe305', 'Chleb', 1, 'szt', 5);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('7bad03a3-086c-4edf-b85f-a6e151abe305', 1, 'Jajka roztrzepać, doprawić solą. Szynkę pokroić w kostkę, ser zetrzeć.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('7bad03a3-086c-4edf-b85f-a6e151abe305', 2, 'Na patelni rozgrzać olej, wlać jajka. Gdy dół się zetnie, posypać szynką i serem, złożyć na pół.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('7bad03a3-086c-4edf-b85f-a6e151abe305', 3, 'Smażyć jeszcze chwilę. Podawać z pieczywem i warzywami.');
INSERT INTO recipes (id, name, description) VALUES ('1a5888bb-bc69-48bb-ba67-ec961bbf39a4', 'Twaróg na słodko z owocami', 'Lekka kolacja – twaróg z bananem i miodem.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('1a5888bb-bc69-48bb-ba67-ec961bbf39a4', 'Twaróg', 200, 'g', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('1a5888bb-bc69-48bb-ba67-ec961bbf39a4', 'Banany', 1, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('1a5888bb-bc69-48bb-ba67-ec961bbf39a4', 'Jogurt naturalny', 2, 'szt', 3);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('1a5888bb-bc69-48bb-ba67-ec961bbf39a4', 1, 'Twaróg przełożyć do miseczki, rozgnieść widelcem. Wymieszać z jogurtem.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('1a5888bb-bc69-48bb-ba67-ec961bbf39a4', 2, 'Banana pokroić w plasterki, ułożyć na twarogu.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('1a5888bb-bc69-48bb-ba67-ec961bbf39a4', 3, 'Opcjonalnie skropić miodem lub posypać płatkami. Podawać od razu.');
INSERT INTO recipes (id, name, description) VALUES ('d76a1f63-dc35-4fb1-9ad7-07e1e3292d48', 'Zapiekanka z kiełbasą i serem', 'Prosta zapiekanka – kiełbasa, ziemniaki i ser.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('d76a1f63-dc35-4fb1-9ad7-07e1e3292d48', 'Ziemniaki', 500, 'g', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('d76a1f63-dc35-4fb1-9ad7-07e1e3292d48', 'Kiełbasa', 1, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('d76a1f63-dc35-4fb1-9ad7-07e1e3292d48', 'Ser żółty', 100, 'g', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('d76a1f63-dc35-4fb1-9ad7-07e1e3292d48', 'Jajka', 1, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('d76a1f63-dc35-4fb1-9ad7-07e1e3292d48', 'Jogurt naturalny', 2, 'szt', 5);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('d76a1f63-dc35-4fb1-9ad7-07e1e3292d48', 'Olej', 1, 'szt', 6);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('d76a1f63-dc35-4fb1-9ad7-07e1e3292d48', 1, 'Ziemniaki ugotować w mundurkach, ostudzić, pokroić w plastry. Kiełbasę pokroić w plasterki, ser zetrzeć.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('d76a1f63-dc35-4fb1-9ad7-07e1e3292d48', 2, 'W naczyniu żaroodpornym ułożyć warstwami ziemniaki, kiełbasę i ser. Przełożyć jogurtem zmieszanym z jajkiem.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('d76a1f63-dc35-4fb1-9ad7-07e1e3292d48', 3, 'Zapiec w piekarniku (180°C) ok. 25 min do zrumienienia. Podawać z surówką.');
INSERT INTO recipes (id, name, description) VALUES ('a4ab6176-c4c8-4341-8a27-4710ca1d3f1a', 'Tosty z awokado i jajkiem', 'Kolacja w stylu brunch – tosty z awokado i jajkiem sadzonym.');
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a4ab6176-c4c8-4341-8a27-4710ca1d3f1a', 'Pieczywo tostowe', 2, 'szt', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a4ab6176-c4c8-4341-8a27-4710ca1d3f1a', 'Awokado', 1, 'szt', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a4ab6176-c4c8-4341-8a27-4710ca1d3f1a', 'Jajka', 2, 'szt', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a4ab6176-c4c8-4341-8a27-4710ca1d3f1a', 'Olej', 1, 'szt', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('a4ab6176-c4c8-4341-8a27-4710ca1d3f1a', 'Sól', 1, 'szt', 5);
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('a4ab6176-c4c8-4341-8a27-4710ca1d3f1a', 1, 'Chleb opiekać w tosterze. Jajka usmażyć na oleju (sadzone lub jajecznica).');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('a4ab6176-c4c8-4341-8a27-4710ca1d3f1a', 2, 'Awokado rozgnieść widelcem, doprawić solą i sokiem z cytryny. Na tosty nałożyć awokado, położyć jajko.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('a4ab6176-c4c8-4341-8a27-4710ca1d3f1a', 3, 'Opcjonalnie posypać pieprzem lub papryką. Podawać od razu.');
